<script setup>
import { ref, computed } from 'vue'
import Icon from '../components/Icon.vue'
import Trend from '../components/Trend.vue'
import Chart from '../components/Chart.vue'
import Donut from '../components/Donut.vue'
import BarList from '../components/BarList.vue'
import { sales, traffic } from '../data'
const emit = defineEmits(['action','download'])
const period = ref('1M'), selectedHour = ref(''), team = ref([])
const factor = computed(() => ({'14D':.47,'1M':1,'3M':2.8,'6M':5.5})[period.value])
const hours = Array.from({length:168},(_,i) => {const day = Math.floor(i/24), h = i%24, profile = .025 + .3*Math.exp(-(((h-12)/4)**2)) + .66*Math.exp(-(((h-20.5)/3.5)**2)), scale = [.73,.78,.83,.89,.92,1,.96][day]; return {day:['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][day], h, intensity: Math.max(.035,profile*scale), amount: Math.round(profile*scale*7100)} })
function invite() { emit('action',{title:'Invite members',type:'invite',onSave: email => team.value.push(email)}) }
</script>
<template><div class="dashboard dashboard-nine">
  <div class="page-title"><h1>Welcome back, Shaban! 👋</h1><button @click="emit('action',{title:'New product',type:'product'})"><Icon name="plus"/>New Product</button></div>
  <div class="grid four commerce-kpis"><section v-for="(stat,i) in [['Total revenue','$284,920','8.2%','wallet'],['Orders','1,842','4.1%','cart'],['Average order value','$154.60','1.3%','card'],['Store conversion','3.06%','0.6%','funnel']]" :key="stat[0]" class="corner-card"><p><Icon :name="stat[3]" :size="13"/>{{stat[0]}}</p><h2>{{stat[1]}}</h2><Trend :value="stat[2]" :negative="i === 2" plain suffix="vs prior 30 days"/><div class="mini-segments"><span v-for="(h,j) in [21,29,35,41,36,49,30,27]" :key="j" :style="{height: (i === 2 ? 61-h : h) + 'px'}"></span></div></section></div>
  <div class="commerce-sales"><section class="corner-card total-sales"><div class="section-summary"><div><h2>${{Math.round(413*factor)}}K</h2><p>Total Sales in last {{period === '14D' ? '14 days' : period === '1M' ? '30 days' : period === '3M' ? '90 days' : '180 days'}}</p><div class="legend"><span>New user</span><span>Existing user</span></div></div><div class="align-right"><div class="segmented-control compact"><button v-for="p in ['14D','1M','3M','6M']" :key="p" :class="{active:period === p}" @click="period=p">{{p}}</button></div><Trend value="1.5%" plain suffix="vs last 30 days"/></div></div><Chart :values="sales.map(v=>v * (period === '14D' ? .8 : 1))" :secondary="sales.map(v=>v*.38)" type="segmented" :max="20" :height="320" :labels="['Mar 22','Mar 26','Mar 30','Apr 3','Apr 7','Apr 11','Apr 15','Apr 19']" :y-labels="['20k','15k','10k','5k','0k']"/></section>
    <section class="corner-card campaign-revenue"><div class="section-summary"><div><h2>$92.5K</h2><p>Revenue from campaigns in Aug</p></div><Trend value="5.2%" plain/></div><Chart :values="[34,67,45,58,74,59,83,92,39,53,71,62]" type="campaign" :height="320" :grid="true" :labels="['Jan','Mar','May','Jul','Sep','Nov']"/></section></div>
  <div class="grid two commerce-conversions"><section class="corner-card funnel-card"><div class="section-summary"><div><h2>7.8%</h2><p>Overall purchase rate · 5.64K orders from 72K views · Last 30 days</p></div><div class="align-right"><Trend value="0.4%" plain/><p>vs prior 30 days</p></div></div><div class="conversion-funnel"><div v-for="(stage,i) in [['72K','100%','Product views'],['38.2K','53%','Add to cart'],['16.8K','23%','Checkout'],['5.64K','8%','Purchase']]" :key="stage[0]" class="funnel-stage"><strong>{{stage[0]}}</strong><svg viewBox="0 0 150 200" preserveAspectRatio="none" aria-hidden="true"><path :d="`M0 ${100-[60,32,15,5][i]} C65 ${100-[60,32,15,5][i]},75 ${100-[32,15,5,3][i]},150 ${100-[32,15,5,3][i]} L150 ${100+[32,15,5,3][i]} C75 ${100+[32,15,5,3][i]},65 ${100+[60,32,15,5][i]},0 ${100+[60,32,15,5][i]}Z`" :fill="['#bdbdbd','#8e8e8e','#525252','#303030'][i]" stroke="#5b5b5b" stroke-width="8"/></svg><span class="funnel-percent">{{stage[1]}}</span><small>{{stage[2]}}</small></div></div></section>
    <section class="corner-card channel-orders"><div class="section-summary"><div><h2>1,842</h2><p>Total orders in last 30 days</p></div><div class="align-right"><Trend value="0.5%" plain/><p>vs prior 30 days</p></div></div><div class="channel-body"><Donut :values="[37.9,28,15,12,7.1]" striped/><ul class="channel-legend"><li v-for="(r,i) in [['Organic search','37.9%','698'],['Direct','28.0%','516'],['Referral','15.0%','276'],['Paid social','12.0%','221'],['Others','7.1%','131']]" :key="r[0]"><i :style="{background:['#ddd','#aaa','#777','#444','#222'][i]}"></i><span>{{r[0]}}</span><small>{{r[1]}}</small><small>{{r[2]}}</small></li></ul></div></section></div>
  <div class="grid four commerce-bottom"><section class="corner-card"><div class="section-title"><h3><Icon name="cohort" :size="13"/>Traffic sources</h3><span>12 months</span></div><BarList :items="traffic" segmented/></section>
  <section class="corner-card team-card"><div class="section-title"><h3><Icon name="users" :size="13"/>Team</h3></div><div class="team-empty"><div class="avatar-group"><span class="avatar illustrated">CN</span><span class="avatar light-avatar">SH</span></div><h4>{{team.length ? team.length + ' team member invited' : 'No Team Members'}}</h4><p v-if="!team.length">Invite your team to<br>collaborate on this project.</p><p v-else>{{team.at(-1)}}</p><button @click="invite"><Icon name="plus" :size="14"/>Invite Members</button></div></section>
  <section class="corner-card heatmap-card"><div class="section-title"><h3><Icon name="clock" :size="13"/>Sales by hour</h3><span>Last 7 days</span></div><div class="section-summary"><div><h2>$4.8K</h2><p>Peak · Sat 9p–10p</p></div><div class="align-right"><strong>$1.5K</strong><p>Avg / hour</p></div></div><div class="heatmap"><div class="heatmap-days"><span v-for="day in ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']" :key="day">{{day}}</span></div><div class="heatmap-cells"><button v-for="(hour,i) in hours" :key="i" :style="{background: `rgba(200,200,200,${hour.intensity})`}" :title="`${hour.day} ${hour.h}:00 · $${hour.amount.toLocaleString()}`" :aria-label="`${hour.day} ${hour.h}:00: $${hour.amount} in sales`" :class="{selected:selectedHour === i}" @click="selectedHour = selectedHour === i ? '' : i"></button></div></div><div class="heatmap-axis"><span>12a</span><span>6a</span><span>12p</span><span>6p</span><span>12a</span></div><div class="heatmap-key"><small>{{selectedHour !== '' ? `${hours[selectedHour].day} ${hours[selectedHour].h}:00 · $${hours[selectedHour].amount.toLocaleString()}` : 'Lower'}}</small><template v-if="selectedHour === ''"><i v-for="n in 5" :key="n" :style="{opacity:n/5}"></i><small>Higher</small></template></div></section>
  <section class="corner-card quick-actions"><div class="section-title"><h3><Icon name="zap" :size="13"/>Quick actions</h3></div><button v-for="a in [['plus','Add Campaign','Create a Campaign.'],['truck','Review unfulfilled','Orders waiting to ship.'],['settings','Workspace settings','Team, roles, permissions.'],['download','Export sales','CSV for accountings.']]" :key="a[1]" @click="a[0] === 'download' ? emit('download',{name:'sales',headings:['Day','Sales'],rows:sales.map((v,i)=>[i+1,v*1000])}) : emit('action',{title:a[1],type:a[0] === 'plus' ? 'campaign' : undefined,body:a[2]})"><Icon :name="a[0]"/><span>{{a[1]}}<small>{{a[2]}}</small></span><Icon name="right" :size="13"/></button></section></div>
</div></template>
